import React from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, Image } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

export default function MyScheduleScreen() {
  const appointments = [
    {
      id: 1,
      doctor: 'Dr. Sarah Wilson',
      specialty: 'Cardiologist',
      date: 'Today',
      time: '2:30 PM',
      image: 'https://randomuser.me/api/portraits/women/32.jpg',
      status: 'upcoming'
    },
    {
      id: 2,
      doctor: 'Dr. James Brown',
      specialty: 'Dermatologist',
      date: 'Tomorrow',
      time: '10:00 AM',
      image: 'https://randomuser.me/api/portraits/men/45.jpg',
      status: 'upcoming'
    },
    {
      id: 3,
      doctor: 'Dr. Emily Davis',
      specialty: 'Pediatrician',
      date: 'Wed, 15 Mar',
      time: '3:45 PM',
      image: 'https://randomuser.me/api/portraits/women/68.jpg',
      status: 'upcoming'
    }
  ];

  return (
    <ScrollView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>My Schedule</Text>
      </View>

      {/* Upcoming Appointments */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Upcoming Appointments</Text>
        {appointments.map((appointment) => (
          <View key={appointment.id} style={styles.appointmentCard}>
            <View style={styles.appointmentHeader}>
              <View style={styles.doctorInfo}>
                <Image 
                  source={{ uri: appointment.image }}
                  style={styles.doctorImage}
                />
                <View>
                  <Text style={styles.doctorName}>{appointment.doctor}</Text>
                  <Text style={styles.specialty}>{appointment.specialty}</Text>
                </View>
              </View>
              <View style={styles.statusBadge}>
                <Text style={styles.statusText}>Upcoming</Text>
              </View>
            </View>
            <View style={styles.appointmentDetails}>
              <View style={styles.detailItem}>
                <Ionicons name="calendar" size={20} color="#007AFF" />
                <Text style={styles.detailText}>{appointment.date}</Text>
              </View>
              <View style={styles.detailItem}>
                <Ionicons name="time" size={20} color="#007AFF" />
                <Text style={styles.detailText}>{appointment.time}</Text>
              </View>
            </View>
            <View style={styles.actionButtons}>
              <TouchableOpacity style={[styles.actionButton, styles.rescheduleButton]}>
                <Text style={styles.rescheduleText}>Reschedule</Text>
              </TouchableOpacity>
              <TouchableOpacity style={[styles.actionButton, styles.cancelButton]}>
                <Text style={styles.cancelText}>Cancel</Text>
              </TouchableOpacity>
            </View>
          </View>
        ))}
      </View>

      {/* Past Appointments */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Past Appointments</Text>
        <View style={styles.pastAppointmentCard}>
          <View style={styles.appointmentHeader}>
            <View style={styles.doctorInfo}>
              <Image 
                source={{ uri: 'https://randomuser.me/api/portraits/men/22.jpg' }}
                style={styles.doctorImage}
              />
              <View>
                <Text style={styles.doctorName}>Dr. Michael Johnson</Text>
                <Text style={styles.specialty}>General Physician</Text>
              </View>
            </View>
            <View style={[styles.statusBadge, styles.completedBadge]}>
              <Text style={[styles.statusText, styles.completedText]}>Completed</Text>
            </View>
          </View>
          <View style={styles.appointmentDetails}>
            <View style={styles.detailItem}>
              <Ionicons name="calendar" size={20} color="#666" />
              <Text style={[styles.detailText, styles.pastDetailText]}>Mon, 13 Mar</Text>
            </View>
            <View style={styles.detailItem}>
              <Ionicons name="time" size={20} color="#666" />
              <Text style={[styles.detailText, styles.pastDetailText]}>11:30 AM</Text>
            </View>
          </View>
        </View>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#F5F5F5',
  },
  header: {
    padding: 20,
    backgroundColor: '#fff',
  },
  headerTitle: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#333',
  },
  section: {
    padding: 20,
  },
  sectionTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    marginBottom: 15,
    color: '#333',
  },
  appointmentCard: {
    backgroundColor: '#fff',
    borderRadius: 15,
    padding: 15,
    marginBottom: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  appointmentHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 15,
  },
  doctorInfo: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  doctorImage: {
    width: 50,
    height: 50,
    borderRadius: 25,
    marginRight: 10,
  },
  doctorName: {
    fontSize: 16,
    fontWeight: 'bold',
    color: '#333',
  },
  specialty: {
    fontSize: 14,
    color: '#666',
  },
  statusBadge: {
    backgroundColor: '#E3F2FD',
    paddingHorizontal: 10,
    paddingVertical: 5,
    borderRadius: 15,
  },
  statusText: {
    color: '#007AFF',
    fontSize: 12,
    fontWeight: '500',
  },
  completedBadge: {
    backgroundColor: '#E8F5E9',
  },
  completedText: {
    color: '#4CAF50',
  },
  appointmentDetails: {
    flexDirection: 'row',
    marginBottom: 15,
  },
  detailItem: {
    flexDirection: 'row',
    alignItems: 'center',
    marginRight: 20,
  },
  detailText: {
    marginLeft: 5,
    color: '#007AFF',
    fontSize: 14,
  },
  pastDetailText: {
    color: '#666',
  },
  actionButtons: {
    flexDirection: 'row',
    justifyContent: 'space-between',
  },
  actionButton: {
    flex: 1,
    padding: 10,
    borderRadius: 8,
    alignItems: 'center',
    marginHorizontal: 5,
  },
  rescheduleButton: {
    backgroundColor: '#E3F2FD',
  },
  rescheduleText: {
    color: '#007AFF',
    fontWeight: '500',
  },
  cancelButton: {
    backgroundColor: '#FFEBEE',
  },
  cancelText: {
    color: '#F44336',
    fontWeight: '500',
  },
  pastAppointmentCard: {
    backgroundColor: '#fff',
    borderRadius: 15,
    padding: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
});
